+/// Extract grapheme clusters from either end of a string.
+#[cold]
+fn extract_graphemes(string: &str, repeat: usize, from_end: bool) -> StrResult<Str> {
+    if repeat == 0 {
+        return Err(eco_format!("repeat must be at least 1"));
+    }
+
+    let graphemes: Vec<&str> = string.graphemes(true).collect();
+    if repeat > graphemes.len() {
+        return Err(eco_format!(
+            "not enough characters (requested {}, but string only has {})",
+            repeat,
+            graphemes.len()
+        ));
+    }
+
+    let start = if from_end { graphemes.len() - repeat } else { 0 };
+    let end = if from_end { graphemes.len() } else { repeat };
+    Ok(graphemes[start..end].concat().into())
+}
